head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/*
 * 1. 화일명     :    utils.js
 * 2. 작성일자   :    2008-02-01
 * 3. 작성자     :    한지연
 * 4. 설명       :    각종  utility 함수를 가지고 있는 화일.
 */

/*
 * <pre>
 * format의 형태로 클라이언트 pc의 현재 날자를 리턴하는 메소드
 *
 * 1. 설 명
 *    format의 형태로 클라이언트 pc의 현재 날자를 리턴
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   format - "yyyymmdd", "yyyy-mm-dd", "yyyymmddhhmmss", "yyyy-mm-dd hh:mm:ss".
 * 
 * <b>return</b>
 *   소스 문자열을 trim한 문자열
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetToday2
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetToday2 = function() {
    return scwin.cGetToday("yyyymmdd");
};
/**
 * @method
 * @name cGetToday
 * @description desc
 * @param {string} format desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetToday = function(format) {
    var dNow = new Date();
    var yyyy = "";
    var MM = "";
    var dd = "";
    var hh = "";
    var mm = "";
    var sss = "";
    yyyy = dNow.getYear();
    MM = dNow.getMonth() + 1;
    dd = dNow.getDate();
    hh = dNow.getHours();
    mm = dNow.getMinutes();
    sss = dNow.getSeconds();
    yyyy = scwin.cGetZero(yyyy, 4);
    MM = scwin.cGetZero(MM, 2);
    dd = scwin.cGetZero(dd, 2);
    hh = scwin.cGetZero(hh, 2);
    mm = scwin.cGetZero(mm, 2);
    sss = scwin.cGetZero(sss, 2);
    if (format == "yyyymmdd") return (yyyy + MM + dd);

    else if (format == "yyyy-mm-dd") return (yyyy + "-" + MM + "-" + dd);

    else if (format == "yyyymmddhhmmss") return (yyyy + MM + dd + hh + mm + sss);

    else if (format == "yyyy-mm-dd hh:mm:ss") return (yyyy + "-" + MM + "-" + dd + " " + hh + ":" + mm + ":" + sss);
};


/*
 * <pre>
 * yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 증가한 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 증가한 날짜를 리턴
 *    
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   yyyy - 년
 *   mm - 월
 *   dd - 일
 *   val - 증가치
 *
 * <b>return</b>
 *   yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 증가한 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetPlusMonth
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @param {string} dd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetPlusMonth = function(yyyy, mm, dd, val) {
    var iYear = new Number(yyyy);
    var iMonth = new Number(mm);
    var iDay = new Number(dd);
    var ival = new Number(val);
    var iAddYear = 0;
    if (ival >= 12) {
        iAddYear = new Number(ival / 12);
        iYear = iYear + iAddYear;
        iMonth = iMonth + (ival % 12);
    } else {
        ival += iMonth;
        if (ival > 12) {
            iYear = iYear + 1;
            iMonth = ival - 12;
        } else {
            iMonth = ival;
        }
    }

    // 
    iMaxDay = scwin.cGetMaxDay(iYear, iMonth);
    if (iDay > iMaxDay) {
        iDay = iMaxDay;
    }

    // 1차 : 2개월 : 20040201 ~ 20040401
    // 최종계산 : 20040201 ~ 20040331
    // 따라서 1차 계산된 일자에서 하루를 빼서 리턴함.

    return scwin.cGetMinusDate(iYear.toString(), scwin.cGetZero(iMonth.toString(), 2), scwin.cGetZero(iDay.toString(), 2), 1);
};



// 년도 더하기
/**
 * @method
 * @name cGetPlusYear
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetPlusYear = function(yyyymmdd, val) {
    var yyyy = parseInt(yyyymmdd.substring(0, 4), 10) + parseInt(val, 10);
    //var yyyy = yyyymmdd.substring(0,4) + val;
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    return yyyy + mm + dd;
};


// 년도에서 빼기
/**
 * @method
 * @name cGetMinusYear
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetMinusYear = function(yyyymmdd, val) {
    var yyyy = yyyymmdd.substring(0, 4) - val;
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    return yyyy + mm + dd;
};


/*
 * <pre>
 * yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 감소한 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 감소한 날짜를 리턴
 *    
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   yyyy - 년
 *   mm - 월
 *   dd - 일
 *   val - 감소치
 *
 * <b>return</b>
 *   yyyy, mm, dd 로 받은 날짜에서 val만큼 월을 감소한 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetMinusMonth
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @param {string} dd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetMinusMonth = function(yyyy, mm, dd, val) {
    var iYear = new Number(yyyy);
    var iMonth = new Number(mm);
    var iDay = new Number(dd);
    var ival = new Number(val);
    ival = iMonth - ival;
    if (ival <= 0) {
        iYear = iYear - 1;
        iMonth = 12 - ival * (-1);
    } else {
        iMonth = ival;
    }
    return (iYear.toString() + scwin.cGetZero(iMonth.toString(), 2) + scwin.cGetZero(iDay.toString(), 2));
};


/*
 * <pre>
 * yyyymmdd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyymmdd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴
 *    
 * 2. 특이사항
 *    각 아규먼트들은 integer, string 타입 모두 가능
 * 
 * <b>Parameters</b>
 *   yyyymmdd - 년월일
 *   val - 감소치
 *
 * <b>return</b>
 *   yyyymmdd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetMinusDate2
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetMinusDate2 = function(yyyymmdd, val) {
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    return scwin.cGetMinusDate(yyyy, mm, dd, val);
};


/*
 * <pre>
 * yyyy, mm, dd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyy, mm, dd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴
 *    
 * 2. 특이사항
 *    각 아규먼트들은 integer, string 타입 모두 가능
 * 
 * <b>Parameters</b>
 *   yyyy - 년
 *   mm - 월
 *   dd - 일
 *   val - 감소치
 *
 * <b>return</b>
 *   yyyy, mm, dd 로 받은 날짜에서 val만큼 감소된 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetMinusDate
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @param {string} dd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetMinusDate = function(yyyy, mm, dd, val) {
    var iYear = new Number(yyyy);
    var iMonth = new Number(mm);
    var iDay = new Number(dd);
    var ival = new Number(val);
    var iMaxDay = 0;
    var isTrue = true;
    if (iDay > ival) {
        iDay = iDay - ival;
        isTrue = false;
    } else if (ival == iDay) {
        ival = 0;
    } else ival = ival - iDay;
    while (isTrue) {
        if (iMonth == 1) {
            iYear = iYear - 1;
            iMonth = 12;
        } else {
            iMonth = iMonth - 1;
        }
        iMaxDay = scwin.cGetMaxDay(iYear, iMonth);
        if (ival == 0) {
            ival = iMaxDay;
            iDay = ival;
            break;
        } else if (ival < iMaxDay) {
            iDay = iMaxDay - ival;
            break;
        } else {
            ival = ival - iMaxDay;
        }
    }
    return (iYear.toString() + scwin.cGetZero(iMonth.toString(), 2) + scwin.cGetZero(iDay.toString(), 2));
};


/*
 * <pre>
 * yyyymmdd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyymmdd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴
 *    
 * 2. 특이사항
 *    각 아규먼트들은 integer, string 타입 모두 가능
 * 
 * <b>Parameters</b>
 *   yyyymmdd - 년월일
 *   val - 증가치
 *
 * <b>return</b>
 *   yyyymmdd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetPlusDate2
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetPlusDate2 = function(yyyymmdd, val) {
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    return scwin.cGetPlusDate(yyyy, mm, dd, val);
};



/*
 * <pre>
 * yyyy, mm, dd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴하는 메소드
 *
 * 1. 설 명
 *    yyyy, mm, dd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴
 *    
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   yyyy - 년
 *   mm - 월
 *   dd - 일
 *   val - 증가치
 *
 * <b>return</b>
 *   yyyy, mm, dd 로 받은 날짜에서 val만큼 증가한 날짜를 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetPlusDate
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @param {string} dd desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetPlusDate = function(yyyy, mm, dd, val) {
    var iYear = new Number(yyyy);
    var iMonth = new Number(mm);
    var iDay = new Number(dd);
    var ival = new Number(val);
    ival += iDay;
    var iMaxDay = 0;
    while (true) {
        iMaxDay = scwin.cGetMaxDay(iYear, iMonth);
        if (ival <= iMaxDay) {
            iDay = ival;
            break;
        } else {
            if (iMonth == 12) {
                iYear = iYear + 1;
                iMonth = 1;
            } else {
                iMonth = iMonth + 1;
            }
            ival = ival - iMaxDay;
        }
    }
    return (iYear.toString() + scwin.cGetZero(iMonth.toString(), 2) + scwin.cGetZero(iDay.toString(), 2));
};



/*
 * <pre>
 * 두 날짜의 차이를 날(日)수로 리턴하는 메소드
 *
 * 1. 설 명
 *    두 날짜의 차이를 날(日)수로 리턴
 *    
 * 2. 특이사항
 *    basicDayStr에서 compareDayStr을 뺀 날짜수 리턴
 *    날짜 형식은 "YYYY-MM-DD" 또는 "YYYYMMDD"
 * 
 * <b>Parameters</b>
 *   basicDayStr - "YYYY-MM-DD" 또는 "YYYYMMDD"
 *   compareDayStr - "YYYY-MM-DD" 또는 "YYYYMMDD"
 *
 * <b>return</b>
 *   두 날짜의 차이를 날(日)수로 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetDifTodayInputday
 * @description desc
 * @param {string} basicDayStr desc
 * @param {string} compareDayStr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetDifTodayInputday = function(basicDayStr, compareDayStr) {
    basicDayStr = scwin.cRmString(basicDayStr, '-'); // '-'가 있다면 제거 
    compareDayStr = scwin.cRmString(compareDayStr, '-');
    if (!cIsDate(basicDayStr) || !cIsDate(compareDayStr)) return false; //날짜 형식이 아니라면

    date1 = new Date();
    date2 = new Date();
    date1.setYear(basicDayStr.substring(0, 4));
    date1.setMonth(basicDayStr.substring(4, 6) - 1);
    date1.setDate(basicDayStr.substring(6, 8));
    date2.setYear(compareDayStr.substring(0, 4));
    date2.setMonth(compareDayStr.substring(4, 6) - 1);
    date2.setDate(compareDayStr.substring(6, 8));
    var v_date1 = cGetDateNum(cGetDateTime(date1)); // date를 초로 변환
    var v_date2 = cGetDateNum(cGetDateTime(date2));
    var rtVal = v_date1 - v_date2;
    if (rtVal != 0) rtVal = rtVal / (24 * 60 * 60); // 1일 = 24*60*60 = 86,400초


    else rtVal = 0;
    return rtVal;
};


/*
 * <pre>
 * pString에서 pRmChar을 제거하는 함수
 * 
 * <b>pString</b>
 *   원본 문자열
 *
 * <b>pRmChar</b>
 *   제거할 문자열
 * 
 * <b>return</b>
 *   pString 에서 pRmChar이 제거된 문자열
 * 
 * </pre>
 */
/**
 * @method
 * @name cRmString
 * @description desc
 * @param {string} pString desc
 * @param {string} pRmChar desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cRmString = function(pString, pRmChar) {
    var reg = new RegExp(pRmChar, "ig");
    return pString.replace(reg, "");
};


/*
 * <pre>
 * 입력받은 년,월의 최대 일자을 구하는 메소드
 *
 * 1. 설 명
 *    입력받은 년,월의 최대 일자을 구함.
 *    
 * 2. 특이사항
 *    yyyy, mm 은 String, Integer 모두 가능
 * 
 * <b>Parameters</b>
 *   yyyy - 년
 *   mm - 월
 * 
 * <b>return</b>
 *   년, 월에 해당하는 최대 일자.
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetMaxDay
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetMaxDay = function(yyyy, mm) {
    if (scwin.cIsNull(yyyy) || scwin.cIsNull(mm)) return false; //공백이라면

    var monthDD = new Array(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
    var iMaxDay = 0;
    if (scwin.cIsLeafYear(yyyy)) {
        monthDD[1] = 29;
    }
    iMaxDay = monthDD[new Number(mm) - 1];
    return iMaxDay;
};


/*
 * <pre>
 * 문자열(str) 윤년인지 체크하는 메소드
 *
 * 1. 설 명
 *    문자열(str) 윤년인지 체크
 * 
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   str : 체크할 문자열
 * 
 * <b>return</b>
 *   문자열(str) 윤년인지 체크
 * 
 * </pre>
 */
/**
 * @method
 * @name cIsLeafYear
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cIsLeafYear = function(str) {
    if (scwin.cIsNull(str)) return false; //공백이라면
    var YYYY = new Number(str);
    if (((YYYY % 4 == 0) && (YYYY % 100 != 0)) || (YYYY % 400 == 0)) {
        return true;
    }
    return false;
};


/*
 * <pre>
 * input 필드 객체(obj)의 값이 올바른 주민번호인지 체크하는 메소드
 *
 * 1. 설 명
 *    input 필드 객체(obj)의 값이 올바른 주민번호인지 체크
 *    
 * 2. 특이사항
 * 
 * <b>Parameters</b>
 *   obj - 주민번호를 가진 obj나 value
 *
 * <b>return</b>
 *   input 필드 객체(obj)의 값이 올바른 주민번호인지 체크하여 맞으면 true 리턴.
 * 
 * </pre>
 */
/**
 * @method
 * @name cIsJumin
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cIsJumin = function(obj) {
    var str = "";
    if (typeof obj == "object") str = obj.getValue();

    else str = obj;
    if (scwin.cIsNull(str)) return false; //공백이라면

    str = scwin.cRmString(str, "-"); // "-" 제거
    var j = 9;
    var id_chk = 0;
    object = new Array(13);
    for (var i = 0; i < 13; i++) {
        object[i] = str.substring(i, i + 1);
    }
    var chkdigit = str.substring(12, 13);
    for (var i = 0; i < 12; i++) {
        if (i == 8) j = 9;
        object[i] = object[i] * j;
        j--;
        id_chk += object[i];
    }
    if (((id_chk % 11 == 0) && (chkdigit == 1)) || ((id_chk % 11 == 10) && (chkdigit == 0))) {
        return true;
    } else if ((id_chk % 11 != 0) && (id_chk % 11 != 10) && (id_chk % 11 == chkdigit)) {
        return true;
    } else {
        return false;
    }
};



/*
 * <pre>
 * input 필드 객체(obj)의 값이 올바른 법인번호인지 체크하는 메소드
 *
 * 1. 설 명
 *    input 필드 객체(obj)의 값이 올바른 법인번호인지 체크
 *    
 * 2. 특이사항
 * 
 * <b>Parameters</b>
 *   obj - 법인번호를 가진 obj나 value
 *
 * <b>return</b>
 *   input 필드 객체(obj)의 값이 올바른 법인번호인지 체크하여 맞으면 true 리턴.
 * 
 * </pre>
 */
/**
 * @method
 * @name cIsBupin
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cIsBupin = function(obj) {
    var str = "";
    if (typeof obj == "object") str = obj.getValue();

    else str = obj;
    if (scwin.cIsNull(str)) return false; //공백이라면

    str = scwin.cRmString(str, "-"); // "-" 제거

    var check = 1;
    var no = new Array(13);
    var sum = 0;
    var rem = 0;
    var m = 0;
    m = new Number(str.charAt(12)); // 번호의 마지막 숫자 얻기

    for (var i = 0; i < 12; i++) no[i] = new Number(str.charAt(i)); // 1~12까지 숫자 얻기

    for (var i = 0; i < 12; i++) {
        sum += (check * no[i]);
        check = (check == 1) ? 2 : 1;
    }
    rem = sum % 10; // 나머지 구하기
    rem = 10 - rem;
    rem = (rem >= 10) ? rem - 10 : rem;

    // 마지막번째와 10-rem의 값을 비교
    if (m == rem) return true; // 정확

    else return false; // 부정확
};


/*
 * <pre>
 * input 필드 객체(obj)의 값이 올바른 사업자등록번호인지 체크하는 메소드
 *
 * 1. 설 명
 *    input 필드 객체(obj)의 값이 올바른 사업자등록번호인지 체크
 *    
 * 2. 특이사항
 * 
 * <b>Parameters</b>
 *   obj - 사업자등록번호를 가진 obj나 value
 *
 * <b>return</b>
 *   input 필드 객체(obj)의 값이 올바른 사업자등록번호인지 체크하여 맞으면 true 리턴.
 * 
 * </pre>
 */
/**
 * @method
 * @name cIsResno
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cIsResno = function(obj) {
    var str = "";
    if (typeof obj == "object") str = obj.getValue();

    else str = obj;
    if (scwin.cIsNull(str)) return false; //공백이라면

    str = scwin.cRmString(str, "-"); // "-" 제거

    var check = 0;
    var no = new Array(10);
    var sum = 0;
    var tmpNo = 0;
    var tmpStr = 0;
    for (var i = 0; i < 10; i++) no[i] = new Number(str.charAt(i)); // 1~10까지 숫자 얻기

    for (var i = 0; i < 10; i++) {
        if ((i % 3) == 0) tmpNo = no[i] + 0;

        else if ((i % 3) == 1) tmpNo = no[i] * 3;

        else if ((i % 3) == 2) tmpNo = no[i] * 7;
        if (i == 8) {
            tmpNo = no[i] * 5;
            if (tmpNo > 9) {
                tmpStr = tmpNo + "";
                tmpNo = new Number(tmpStr.charAt(0)) + new Number(tmpStr.charAt(1));
            }
        }
        sum += tmpNo;
    }
    if ((sum % 10) == 0) return true; // 정확

    else return false; // 부정확
};


/*
 * <pre>
 * str이 null, undefined, NaN, 공백("") 이면 true하는 메소드
 *
 * 1. 설 명
 *    str이 null, undefined, NaN, 공백("") 이면 true
 * 
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   str : 체크할 문자열
 * 
 * <b>return</b>
 *   str이 null, undefined, NaN, 공백("") 이면 true
 * 
 * </pre>
 */
/**
 * @method
 * @name cIsNull
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cIsNull = function(str) {
    if (str + "" == "undefined" || str + "" == "NaN" || str + "" == "null" || str + "" == "") return true;
    return false;
};



/*
 * <pre>
 * 문자열 sVal을 iLen길이가 될때까지 sVal의 앞에 "0"을 붙인 문자열을 리턴하는 메소드
 *
 * 1. 설 명
 *    문자열 sVal을 iLen길이가 될때까지 sVal의 앞에 "0"을 붙인 문자열을 리턴
 *    예) sVal에 '23'을 iLen에 5를 주면 리턴값은 '00023' 이다.
 * 
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   sVal - 문자열
 *   iLen - 길이(integer)
 * 
 * <b>return</b>
 *   문자열 sVal을 iLen길이가 될때까지 sVal의 앞에 "0"을 붙인 문자열을 리턴
 * 
 * </pre>
 */
/**
 * @method
 * @name cGetZero
 * @description desc
 * @param {string} sVal desc
 * @param {string} iLen desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cGetZero = function(sVal, iLen) {
    var sStr = sVal + "";
    for (ii = sStr.length; ii < iLen; ii++) {
        sStr = "0" + sStr;
    }
    return sStr;
};


/*
 * <pre>
 * 해당 문자열 양쪽의 space를 trim하여 제거하는 메소드
 *
 * 1. 설 명
 *    
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   str - 소스 문자열.
 * 
 * <b>return</b>
 *   소스 문자열을 trim한 문자열
 * 
 * </pre>
 */
/**
 * @method
 * @name trim
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.trim = function(str) {
    if (str == undefined || str == null) return "";
    str += "";
    return str.replace(/(^\s*)|(\s*$)/g, "");
};


/*
 * <pre>
 * 해당 문자열의 숫자 여부를 리턴하는  메소드
 *
 * 1. 설 명
 *    숫자만 있으면 true, 숫자이외의 문자가 있으면 false 리턴함.
 * 2. 특이사항
 *    
 * 
 * <b>Parameters</b>
 *   str - 소스 문자열.
 * 
 * <b>return</b>
 *   true, false
 * 
 * </pre>
 */
/**
 * @method
 * @name isNum
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNum = function(str) {
    for (i = 0; i < str.length; i++) {
        var cv = str.charCodeAt(i);
        if (!(0x30 <= cv && cv <= 0x39)) {
            return false;
        }
    }
    return true;
};



/*
	날짜 형식 여부 확인.
*/
/**
 * @method
 * @name isDate
 * @description desc
 * @param {string} dt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDate = function(dt) {
    if (dt == "") return true; // 빈건 체크안함
    if (isNaN(dt)) return false; // 숫자가 아니면 false
    if (dt.length != 8) return false; // 8자리(yyyymmdd)가 아니면 false

    var yy = scwin.toNum(dt.substring(0, 4));
    var mm = scwin.toNum(dt.substring(4, 6)) - 1;
    var dd = scwin.toNum(dt.substring(6, 8));
    var date = new Date(yy, mm, dd);
    if (yy != date.getFullYear() ||
        mm != date.getMonth() ||
        dd != date.getDate()) {
        return false; // 존재하지 않는 날짜
    }
    return true; // 존재하는 날짜
};
/**
 * @method
 * @name toNum
 * @description desc
 * @param {string} val desc
 * @param {string} defVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.toNum = function(val, defVal) {
    defVal = (!defVal) ? 0 : defVal;
    val = new Number(val) + 0;
    return isNaN(val) ? defVal : val;
};


/*
	lpad("1", 2, "0") => "01"
*/
/**
 * @method
 * @name lpad
 * @description desc
 * @param {string} src desc
 * @param {string} len desc
 * @param {string} padStr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.lpad = function(src, len, padStr) {
    var retStr = "";
    var padCnt = Number(len) - String(src).length;
    for (var i = 0; i < padCnt; i++) retStr += String(padStr);
    return retStr + src;
};


/*
	replaceAll("**1234*", "*", "") => "1234"
*/
/**
 * @method
 * @name replaceAll
 * @description desc
 * @param {string} src_str desc
 * @param {string} src_char desc
 * @param {string} tar_char desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.replaceAll = function(src_str, src_char, tar_char) {
    var reg = new RegExp(src_char, "ig");
    return src_str.replace(reg, tar_char);
};
/**
 * @method
 * @name calcDate
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} diff desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcDate = function(yyyymmdd, diff) {
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = parseInt(yyyymmdd.substring(4, 6), 10) - 1;
    var dd = yyyymmdd.substring(6, 8);
    var dateObj = new Date(yyyy, mm, dd);
    var date = dateObj.getDate();
    dateObj.setDate(parseInt(date, 10) + parseInt(diff, 10));
    var newDate;
    yyyy = dateObj.getFullYear();
    mm = dateObj.getMonth() + 1;
    mm = (mm.toString().length == 1) ? "0" + mm.toString() : mm;
    dd = dateObj.getDate();
    dd = (dd.toString().length == 1) ? "0" + dd.toString() : dd;
    return yyyy.toString() + mm.toString() + dd.toString();
};
/**
 * @method
 * @name calcMonth
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} diff desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcMonth = function(yyyymmdd, diff) {
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = parseInt(yyyymmdd.substring(4, 6), 10) - 1;
    var dd = yyyymmdd.substring(6, 8);
    var dateObj = new Date(yyyy, mm, dd);
    var mon = dateObj.getMonth();
    dateObj.setMonth(parseInt(mon, 10) + parseInt(diff, 10));
    var newDate;
    yyyy = dateObj.getFullYear();
    mm = dateObj.getMonth() + 1;
    mm = (mm.toString().length == 1) ? "0" + mm.toString() : mm;
    dd = dateObj.getDate();
    dd = (dd.toString().length == 1) ? "0" + dd.toString() : dd;
    return yyyy.toString() + mm.toString() + dd.toString();
};
/**
 * @method
 * @name calcYear
 * @description desc
 * @param {string} yyyymmdd desc
 * @param {string} diff desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calcYear = function(yyyymmdd, diff) {
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = parseInt(yyyymmdd.substring(4, 6), 10) - 1;
    var dd = yyyymmdd.substring(6, 8);
    var dateObj = new Date(yyyy, mm, dd);
    var year = dateObj.getYear();
    dateObj.setYear(parseInt(year, 10) + parseInt(diff, 10));
    var newDate;
    yyyy = dateObj.getFullYear();
    mm = dateObj.getMonth() + 1;
    mm = (mm.toString().length == 1) ? "0" + mm.toString() : mm;
    dd = dateObj.getDate();
    dd = (dd.toString().length == 1) ? "0" + dd.toString() : dd;
    return yyyy.toString() + mm.toString() + dd.toString();
};


/*
	이메일주소 유효성 체크

*/
/**
 * @method
 * @name email_chk
 * @description desc
 * @param {string} email desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.email_chk = function(email) {
    var invalidChars = "\"|&;!=!*\'\\";
    for (var i = 0; i < invalidChars.length; i++) {
        if (email.indexOf(invalidChars.charAt) != -1) {
            //alert("잘못된 이메일 주소입니다.");
            return false;
        }
    }
    if (email.indexOf("@") == -1) {
        //alert("잘못된 이메일 주소입니다. '@'가 없습니다..");
        return false;
    }
    if (email.indexOf(" ") != -1) {
        //alert("잘못된 이메일 주소입니다.");
        return false;
    }
    if (window.RegExp) {
        var reg1str = "(@.*@)|(\\.\\.)|(@\\.)|(\\.@)|(^\\.)";
        var reg2str = "^.+\\@(\\[?)[a-zA-Z0-9\\-\\.]+\\.([a-zA-Z]{2,3}|[0-9]{1,3})(\\]?)$";
        var reg1 = new RegExp(reg1str);
        var reg2 = new RegExp(reg2str);
        if (reg1.test(email) || !reg2.test(email)) {
            //alert("잘못된 이메일 주소입니다.");
            return false;
        }
    }
    return true;
};
